using Microsoft.EntityFrameworkCore; namespace BanHangTraSua.Models; public class QLTraSuaContext:DbContext{public QLTraSuaContext(DbContextOptions<QLTraSuaContext> o):base(o){} public DbSet<DanhMucMon> DanhMucMon=>Set<DanhMucMon>();public DbSet<MonUong> MonUong=>Set<MonUong>();public DbSet<HoaDon> HoaDon=>Set<HoaDon>();public DbSet<ChiTietHoaDon> ChiTietHoaDon=>Set<ChiTietHoaDon>();protected override void OnModelCreating(ModelBuilder b){b.Entity<DanhMucMon>().HasKey(x=>x.MaDM);b.Entity<DanhMucMon>().Property(x=>x.TenDM).HasMaxLength(50).IsRequired();b.Entity<MonUong>().HasKey(x=>x.MaMon);b.Entity<MonUong>().Property(x=>x.GiaBan).HasColumnType("decimal(18,0)");b.Entity<MonUong>().HasOne(x=>x.DanhMucMon).WithMany(x=>x.MonUong).HasForeignKey(x=>x.MaDM);b.Entity<HoaDon>().HasKey(x=>x.MaHD);b.Entity<HoaDon>().Property(x=>x.TongTien).HasColumnType("decimal(18,0)");b.Entity<ChiTietHoaDon>().HasKey(x=>new{x.MaHD,x.MaMon});b.Entity<ChiTietHoaDon>().Property(x=>x.DonGia).HasColumnType("decimal(18,0)");b.Entity<ChiTietHoaDon>().HasOne(x=>x.HoaDon).WithMany(x=>x.ChiTietHoaDon).HasForeignKey(x=>x.MaHD);b.Entity<ChiTietHoaDon>().HasOne(x=>x.MonUong).WithMany().HasForeignKey(x=>x.MaMon);}}